package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string // PIC X(2) @0 len=2
	BrAcct   string // PIC X(4) @2 len=4
	BrType   string // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"      // PIC X len=1 = "N"
var WsFirstFlag string = "Y"    // PIC X len=1 = "Y"
var WsPrevBranch string = "  "  // PIC X(2) len=2 = SPACES
var WsPrevAcct string = "    "  // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal = decimal.NewFromInt(0)       // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0) // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)  // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 = 0         // PIC 99 len=2 = 0
var WsAmtEd string              // PIC ZZ,ZZ9.99 len=9
var WsBalEd string              // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string              // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var curRec LedgerRec
var ledgerFile *os.File
var ledgerScanner *bufio.Scanner

func fitBal(v decimal.Decimal) decimal.Decimal {
	t := v.Truncate(2)
	scaled := t.Mul(decimal.NewFromInt(100)).IntPart()
	mod := int64(1000000000)
	r := scaled % mod
	return decimal.New(r, -2)
}

func fitBranchTot(v decimal.Decimal) decimal.Decimal {
	t := v.Truncate(2)
	scaled := t.Mul(decimal.NewFromInt(100)).IntPart()
	mod := int64(100000000000)
	r := scaled % mod
	return decimal.New(r, -2)
}

func fitGrandTot(v decimal.Decimal) decimal.Decimal {
	t := v.Truncate(2)
	scaled := t.Mul(decimal.NewFromInt(100)).IntPart()
	mod := int64(100000000000)
	r := scaled % mod
	return decimal.New(r, -2)
}

func formatUnsignedIntPart(intVal int64, intDigits int, tmpl string) string {
	digits := fmt.Sprintf("%0*d", intDigits, intVal)
	firstSig := -1
	for i := 0; i < intDigits; i++ {
		if digits[i] != '0' {
			firstSig = i
			break
		}
	}
	digitIdx := make([]int, len(tmpl))
	d := 0
	for i := 0; i < len(tmpl); i++ {
		ch := tmpl[i]
		if ch == 'Z' || ch == '9' {
			digitIdx[i] = d
			d++
		} else {
			digitIdx[i] = -1
		}
	}
	pFirst := len(tmpl)
	if firstSig != -1 {
		for i, di := range digitIdx {
			if di == firstSig {
				pFirst = i
				break
			}
		}
	}
	out := make([]byte, len(tmpl))
	for i := 0; i < len(tmpl); i++ {
		ch := tmpl[i]
		if ch == ',' {
			if firstSig == -1 {
				out[i] = ' '
			} else {
				if i < pFirst {
					out[i] = ' '
				} else {
					out[i] = ','
				}
			}
		} else if ch == 'Z' {
			if firstSig == -1 {
				out[i] = ' '
			} else {
				di := digitIdx[i]
				if di < firstSig {
					out[i] = ' '
				} else {
					out[i] = digits[di]
				}
			}
		} else if ch == '9' {
			di := digitIdx[i]
			out[i] = digits[di]
		} else {
			out[i] = ch
		}
	}
	return string(out)
}

func formatAmtEd(v decimal.Decimal) string {
	abs := v.Abs()
	t := abs.Truncate(2)
	scaled := t.Mul(decimal.NewFromInt(100)).IntPart()
	intVal := scaled / 100
	frac := scaled % 100
	if frac < 0 {
		frac = -frac
	}
	intVal = intVal % 100000
	intPart := formatUnsignedIntPart(intVal, 5, "ZZ,ZZ9")
	fracStr := fmt.Sprintf("%02d", frac)
	return intPart + "." + fracStr
}

func formatBalEd(v decimal.Decimal) string {
	sign := byte(' ')
	if v.Sign() < 0 {
		sign = byte('-')
	}
	abs := v.Abs()
	t := abs.Truncate(2)
	scaled := t.Mul(decimal.NewFromInt(100)).IntPart()
	intVal := scaled / 100
	frac := scaled % 100
	if frac < 0 {
		frac = -frac
	}
	intVal = intVal % 10000000
	intPart := formatUnsignedIntPart(intVal, 7, "Z,ZZZ,ZZ9")
	fracStr := fmt.Sprintf("%02d", frac)
	return string([]byte{sign}) + intPart + "." + fracStr
}

func formatTotEd(v decimal.Decimal) string {
	sign := byte(' ')
	if v.Sign() < 0 {
		sign = byte('-')
	}
	abs := v.Abs()
	t := abs.Truncate(2)
	scaled := t.Mul(decimal.NewFromInt(100)).IntPart()
	intVal := scaled / 100
	frac := scaled % 100
	if frac < 0 {
		frac = -frac
	}
	intVal = intVal % 1000000000
	intPart := formatUnsignedIntPart(intVal, 9, "ZZZ,ZZZ,ZZ9")
	fracStr := fmt.Sprintf("%02d", frac)
	return string([]byte{sign}) + intPart + "." + fracStr
}

func MainPara() {
	var err error
	ledgerFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	ledgerScanner = bufio.NewScanner(ledgerFile)
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	if WsFirstFlag != "Y" {
		AcctBreakPara()
		BranchBreakPara()
	}
	ledgerFile.Close()
	GrandPara()
}

func ReadPara() {
	if ledgerScanner.Scan() {
		line := ledgerScanner.Text()
		if len(line) < 14 {
			line = line + strings.Repeat(" ", 14-len(line))
		} else if len(line) > 14 {
			line = line[:14]
		}
		curRec.BrBranch = line[0:2]
		curRec.BrAcct = line[2:6]
		curRec.BrType = line[6:7]
		amtStr := line[7:14]
		var n int64 = 0
		for i := 0; i < 7; i++ {
			c := amtStr[i]
			var d int64
			if c >= '0' && c <= '9' {
				d = int64(c - '0')
			} else if c == ' ' {
				d = 0
			} else {
				d = 0
			}
			n = n*10 + d
		}
		curRec.BrAmt = decimal.New(n, -2)
	} else {
		if err := ledgerScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	if WsFirstFlag == "Y" {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func PostPara() {
	WsAmtEd = formatAmtEd(curRec.BrAmt)
	if curRec.BrType == "D" {
		WsBal = fitBal(WsBal.Add(curRec.BrAmt))
		fmt.Fprint(os.Stdout, curRec.BrAcct+" D "+WsAmtEd+"\n")
	} else if curRec.BrType == "C" {
		WsBal = fitBal(WsBal.Sub(curRec.BrAmt))
		fmt.Fprint(os.Stdout, curRec.BrAcct+" C "+WsAmtEd+"\n")
	} else {
		WsSkipped = (WsSkipped + 1) % 100
		fmt.Fprint(os.Stdout, curRec.BrAcct+" ? SKIPPED\n")
	}
}

func AcctBreakPara() {
	WsBalEd = formatBalEd(WsBal)
	fmt.Fprint(os.Stdout, "  ACCOUNT "+WsPrevAcct+" BALANCE:"+WsBalEd+"\n")
	WsBranchTot = fitBranchTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.NewFromInt(0)
}

func BranchBreakPara() {
	WsTotEd = formatTotEd(WsBranchTot)
	fmt.Fprint(os.Stdout, " BRANCH "+WsPrevBranch+" TOTAL:"+WsTotEd+"\n")
	WsGrandTot = fitGrandTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.NewFromInt(0)
}

func GrandPara() {
	WsTotEd = formatTotEd(WsGrandTot)
	fmt.Fprint(os.Stdout, "GRAND TOTAL:"+WsTotEd+"\n")
	skippedStr := fmt.Sprintf("%02d", WsSkipped)
	fmt.Fprint(os.Stdout, "SKIPPED: "+skippedStr+"\n")
}

func main() {
	MainPara()
}
